import{z as n,x as m,o as t,c as d,q as i,j as o,D as e,d as l,s as E,S as r}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"负采样","description":"","frontmatter":{"title":"负采样","date":"2026-09-10T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/negative-sampling.md","filePath":"llm/negative-sampling.md","lastUpdated":1791413859000}'),p={name:"llm/negative-sampling.md"};function A(_,a,B,c,h,u){const s=m("Mermaid");return t(),d("div",null,[a[2]||(a[2]=i('<h1 id="负采样" tabindex="-1">负采样 <a class="header-anchor" href="#负采样" aria-label="Permalink to &quot;负采样&quot;">​</a></h1><div class="epigraph"><p>不必每次对整个词表做 softmax；拉近真正的上下文，再从噪声分布里抽几个词推开，一样能塑造向量几何。</p><footer>—— 据 Mikolov et al., Distributed Representations of Words and Phrases and their Compositionality, NeurIPS 2013 整理</footer></div><p><a href="/llm/word2vec-skipgram">Word2Vec skip-gram</a>写出 \\(P(c\\mid w)\\) 的全词表 softmax。本课不重写两张表。缺口是：\\(O(|V|d)\\) 每步不可行。层次 softmax 是一条路；更常用的是负采样（NEG）：把多分类改成「这个 \\((w,c)\\) 是真窗口还是噪声」的几个逻辑回归。本课只把目标替换钉住，不进入子词切分。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>交叉熵要对所有词型归一化，分母 \\(\\sum_{c&#39;}\\exp(u_w^\\top v_{c&#39;})\\) 随 \\(|V|\\) 线性涨，而真正的正例只有窗口里那几个。绝大多数词型既不是正例，梯度贡献也接近 \\(0\\)，却仍要算点积。缺口不是改分布假设，而是换一个与假设兼容、但只碰少数行的损失。</p>',5)),(t(),o(r,null,{default:e(()=>[E(s,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20STEP%5B%22%E4%B8%80%E6%AD%A5%E8%AE%AD%E7%BB%83%20%E8%A6%81%E7%AE%97%E5%A4%9A%E5%B0%91%E7%82%B9%E7%A7%AF%3F%22%5D%20--%3E%20SM%5B%22%E5%85%A8%E8%AF%8D%E8%A1%A8%20softmax%3A%20%7CV%7C%20%E2%89%88%2010%20%E4%B8%87%E8%A1%8C%22%5D%0A%20%20SM%20--%3E%20C1%5B%22O(%7CV%7C%20d)%2099.9%25%20%E8%AF%8D%E6%A2%AF%E5%BA%A6%20%E2%89%88%200%22%5D%0A%20%20STEP%20--%3E%20NEG%5B%22%E8%B4%9F%E9%87%87%E6%A0%B7%3A%201%20%E6%AD%A3%20%2B%20k%20%E8%B4%9F%22%5D%0A%20%20NEG%20--%3E%20C2%5B%22O(k%20d)%20%E4%B8%8E%E8%AF%8D%E8%A1%A8%E5%A4%A7%E5%B0%8F%E8%84%B1%E9%92%A9%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i('<p>负采样：对每个正对 \\((w,c)\\)，从噪声分布 \\(P_n\\) 抽 \\(k\\) 个 \\(c_i\\)，最大化</p> \\[\\log\\sigma(u_w^\\top v_c)+\\sum_{i=1}^k\\log\\sigma(-u_w^\\top v_{c_i}). \\]<p>\\(\\sigma\\) 是 sigmoid。正例当正类，噪声当负类。\\(P_n\\) 常用词频的 \\(3/4\\) 次幂，压低极高频、抬一点中频。这不是无偏的 \\(P(c\\mid w)\\)，是另外一条能把共现写进几何的目标。</p><p><span class="marginnote">\\(3/4\\) 次幂怎么理解：把词频开 0.75 次方再归一化。「的」的频率若是「猫」的 1 万倍，开 3/4 次方后差距缩成约 1000 倍——高频词仍更常被抽当负例（学会排除它们有价值），但不会垄断全部负例名额。</span></p><h3 id="负采样不是随机抽「错误标签」那么随意" tabindex="-1">负采样不是随机抽「错误标签」那么随意 <a class="header-anchor" href="#负采样不是随机抽「错误标签」那么随意" aria-label="Permalink to &quot;负采样不是随机抽「错误标签」那么随意&quot;">​</a></h3><p>若从均匀分布抽负例，大量负例是生僻词，模型只需学会「非常见词不是上下文」，高频结构学不足。若按原始词频抽，停用词占满负例，梯度噪声大。\\(3/4\\) 次幂是经验折中。把 NEG 理解成「随便挑几个别的词当负类」，后课对比学习的负例设计会失去对照。\\(k\\) 太小则几乎不推开，\\(k\\) 太大则又接近全表代价。</p><p><span class="marginnote">逻辑回归用的是 \\(\\sigma\\)，不是词表 softmax。没有「概率在 \\(V\\) 上求和为 \\(1\\)」这一约束。词向量仍可用来检索近邻，但不要把 \\(u_w^\\top v_c\\) 解释成校准过的 \\(P(c\\mid w)\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每步：取正对，抽 \\(k\\) 个负 \\(c_i\\)，只更新涉及的 \\(u_w\\) 与那些 \\(v\\) 行——稀疏更新，与嵌入查找的 scatter 同一机制。损失对每个 sigmoid 独立，可用上一单元的对数空间避免 \\(\\log\\sigma\\) underflow（\\(\\mathrm{logsigmoid}\\)）。\\(k\\) 常用 \\(5\\)–\\(20\\)。下采样极高频词（另删一些正例）常与 NEG 一起出现，本课视为数据侧技巧，不是损失定义。</p>',9)),(t(),o(r,null,{default:e(()=>[E(s,{id:"mermaid-39",class:"mermaid",graph:"flowchart%20TD%0A%20%20POS%5B%22%E6%AD%A3%E5%AF%B9%20w%20%E4%B8%8E%20c%22%5D%20--%3E%20LOGP%5B%22%E6%8B%89%E9%AB%98%20sigmoid%20%E7%82%B9%E7%A7%AF%22%5D%0A%20%20NOISE%5B%22%E5%99%AA%E5%A3%B0%E5%88%86%E5%B8%83%22%5D%20--%3E%20NEGS%5B%22k%20%E4%B8%AA%E8%B4%9F%E4%B8%8A%E4%B8%8B%E6%96%87%22%5D%0A%20%20NEGS%20--%3E%20LOGN%5B%22%E5%8E%8B%E4%BD%8E%E8%BF%99%E4%BA%9B%E7%82%B9%E7%A7%AF%22%5D%0A%20%20LOGP%20--%3E%20L%5B%22%E6%B1%82%E5%92%8C%E5%8D%B3%20NEG%20%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20LOGN%20--%3E%20L%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>正例梯度把 \\(u_w\\) 与 \\(v_c\\) 的夹角拉小（并可能拉长）；负例把随机抽到的方向推开。几何由「真邻域 vs 噪声邻域」的对比决定，仍符合分布假设，只是对照物从「词表其余全部」换成「\\(k\\) 个噪声」。计算量 \\(O(kd)\\)，与 \\(|V|\\) 脱钩。嵌入表仍然是 \\(|V|\\times d\\)，只是每步只碰 \\(1+k\\) 行量级。</p><p><span class="marginnote">省了多少，代个数字：\\(|V|=10\\) 万、\\(d=300\\)、\\(k=5\\) 时，全 softmax 每步约 \\(10^5\\times300=3000\\) 万次乘加，NEG 只要 \\((1+5)\\times300=1800\\) 次——差四个数量级。嵌入表还是那 10 万行，只是每步只更新其中约 6 行。</span></p><p>层次 softmax 把词表编成二叉树，每步 \\(O(d\\log|V|)\\)，是另一条近似。NEG 更易实现，也更常接到后续的对比学习叙事里。两者都放弃精确配分函数。若下游真要校准的 \\(P(w)\\)，需要重新在全词表上算 softmax 或用其他校准头，不能直接读 NEG 训练出的点积。</p><p>因为目标不是真实 softmax，用这些向量做「下一个词的概率」没有校准。它们适合当特征、当初始化、当近邻检索。接到分类头上仍要重新训练或重新归一化。</p><p><span class="marginnote">常见误区：把 \\(\\sigma(u_w^\\top v_c)\\) 读成「c 是 w 的上下文的概率」。它没有归一化约束，同一个词可以跟谁都点积很高——停用词就是这样。NEG 分数只适合排序近邻、做检索，要校准概率就得换输出头重训。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 BPE，不讲 UNK。下一课<a href="/llm/why-subword">子词的动机</a>问整词表为何不够。后课默认：大词表上的 skip-gram 用 NEG 或同类对比目标训练；不要把 NEG 分数当成校准概率。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>全词表 softmax 每步 \\(O(|V|d)\\)；NEG 改成一个正例加 \\(k\\) 个噪声的逻辑回归。</li><li>噪声分布用词频的 \\(3/4\\) 次幂，不是均匀乱抽。</li><li>每步只更新少数嵌入行；目标不再是校准的 \\(P(c\\mid w)\\)。</li><li>分布假设仍在，对照集变小了。</li><li>出处：Mikolov et al., NeurIPS 2013。</li></ul>',10))])}const k=n(p,[["render",A]]);export{g as __pageData,k as default};
